"""Postgres access for the ingest worker.

Raw SQL rather than an ORM, so there is no second schema definition to keep in
sync with Prisma. Two Prisma details drive the shape of the statements here:

* ``@default(cuid())`` is generated by the Prisma *client*, not by Postgres, so
  every INSERT from this worker has to supply its own primary key.
* ``@updatedAt`` is likewise client-side. There is no trigger, so every UPDATE
  sets "updatedAt" explicitly.

Table names are snake_case (mapped via @@map); column names stay camelCase and
are therefore quoted.
"""

from __future__ import annotations

import logging
import uuid
from typing import Any, Iterable, Sequence

import psycopg
from psycopg.rows import dict_row

log = logging.getLogger(__name__)


def new_id() -> str:
    """Primary key for worker-inserted rows.

    Prisma hands out cuids; these are uuid4 hex. The column is a plain String
    with no format constraint, so the two coexist fine.
    """
    return uuid.uuid4().hex


class Database:
    def __init__(self, dsn: str) -> None:
        self._dsn = dsn
        self._conn: psycopg.Connection | None = None

    def connect(self) -> psycopg.Connection:
        if self._conn is None or self._conn.closed:
            self._conn = psycopg.connect(
                self._dsn, autocommit=True, row_factory=dict_row
            )
        return self._conn

    def close(self) -> None:
        if self._conn is not None and not self._conn.closed:
            self._conn.close()
        self._conn = None

    # ------------------------------------------------------------------ queue

    def requeue_stale_jobs(self, stale_seconds: int, max_attempts: int) -> int:
        """Recover jobs whose worker died mid-run.

        Anything RUNNING without a recent heartbeat goes back to QUEUED, unless
        it has already burned through its attempts, in which case it fails.
        """
        with self.connect().cursor() as cur:
            cur.execute(
                """
                UPDATE video_jobs
                   SET status = CASE
                                  WHEN attempts >= %(max_attempts)s
                                  THEN 'FAILED'::"JobStatus"
                                  ELSE 'QUEUED'::"JobStatus"
                                END,
                       error = CASE
                                 WHEN attempts >= %(max_attempts)s
                                 THEN 'Worker stopped responding'
                                 ELSE error
                               END,
                       "updatedAt" = now()
                 WHERE status = 'RUNNING'::"JobStatus"
                   AND (
                         "heartbeatAt" IS NULL
                      OR "heartbeatAt" < now() - make_interval(secs => %(stale)s)
                       )
                """,
                {"stale": stale_seconds, "max_attempts": max_attempts},
            )
            return cur.rowcount or 0

    def claim_job(self) -> dict[str, Any] | None:
        """Atomically take the oldest queued job.

        FOR UPDATE SKIP LOCKED is what makes it safe to run more than one worker
        replica: two workers never claim the same row.
        """
        conn = self.connect()
        with conn.transaction(), conn.cursor() as cur:
            cur.execute(
                """
                SELECT id, "videoId", attempts
                  FROM video_jobs
                 WHERE status = 'QUEUED'::"JobStatus"
                 ORDER BY "createdAt"
                 LIMIT 1
                   FOR UPDATE SKIP LOCKED
                """
            )
            row = cur.fetchone()
            if row is None:
                return None

            cur.execute(
                """
                UPDATE video_jobs
                   SET status = 'RUNNING'::"JobStatus",
                       attempts = attempts + 1,
                       progress = 0,
                       "commentsIndexed" = 0,
                       error = NULL,
                       "claimedAt" = now(),
                       "heartbeatAt" = now(),
                       "updatedAt" = now()
                 WHERE id = %(id)s
                """,
                {"id": row["id"]},
            )
            return row

    def set_job_meta(
        self, job_id: str, *, title: str, streamer: str, length_seconds: int
    ) -> None:
        with self.connect().cursor() as cur:
            cur.execute(
                """
                UPDATE video_jobs
                   SET title = %(title)s,
                       streamer = %(streamer)s,
                       "lengthSeconds" = %(length)s,
                       "heartbeatAt" = now(),
                       "updatedAt" = now()
                 WHERE id = %(id)s
                """,
                {
                    "id": job_id,
                    "title": title,
                    "streamer": streamer,
                    "length": length_seconds,
                },
            )

    def update_progress(
        self, job_id: str, *, progress: float, comments_indexed: int
    ) -> None:
        """Heartbeat and progress in one write - this is what the UI polls."""
        with self.connect().cursor() as cur:
            cur.execute(
                """
                UPDATE video_jobs
                   SET progress = %(progress)s,
                       "commentsIndexed" = %(indexed)s,
                       "heartbeatAt" = now(),
                       "updatedAt" = now()
                 WHERE id = %(id)s
                """,
                {
                    "id": job_id,
                    "progress": max(0.0, min(100.0, progress)),
                    "indexed": comments_indexed,
                },
            )

    def finish_job(self, job_id: str, *, comments_indexed: int) -> None:
        with self.connect().cursor() as cur:
            cur.execute(
                """
                UPDATE video_jobs
                   SET status = 'DONE'::"JobStatus",
                       progress = 100,
                       "commentsIndexed" = %(indexed)s,
                       error = NULL,
                       "heartbeatAt" = now(),
                       "updatedAt" = now()
                 WHERE id = %(id)s
                """,
                {"id": job_id, "indexed": comments_indexed},
            )

    def fail_job(self, job_id: str, message: str, *, retryable: bool) -> None:
        """Mark a job failed, or hand it back to the queue if it can be retried."""
        with self.connect().cursor() as cur:
            cur.execute(
                """
                UPDATE video_jobs
                   SET status = CASE
                                  WHEN %(retryable)s THEN 'QUEUED'::"JobStatus"
                                  ELSE 'FAILED'::"JobStatus"
                                END,
                       error = %(message)s,
                       "heartbeatAt" = now(),
                       "updatedAt" = now()
                 WHERE id = %(id)s
                """,
                {"id": job_id, "message": message[:500], "retryable": retryable},
            )

    # ------------------------------------------------------------------ data

    def upsert_channel(self, streamer: str) -> str:
        """Channel row for a streamer, created if this is their first VOD."""
        with self.connect().cursor() as cur:
            cur.execute(
                "SELECT id FROM channels WHERE streamer = %s", (streamer,)
            )
            row = cur.fetchone()
            if row:
                return row["id"]

            channel_id = new_id()
            cur.execute(
                """
                INSERT INTO channels (id, streamer, "videoIds")
                VALUES (%(id)s, %(streamer)s, ARRAY[]::text[])
                ON CONFLICT (streamer) DO UPDATE SET streamer = EXCLUDED.streamer
                RETURNING id
                """,
                {"id": channel_id, "streamer": streamer},
            )
            return cur.fetchone()["id"]

    def upsert_video(
        self, video_id: int, channel_id: str, meta: dict[str, Any]
    ) -> str:
        """Video row for this VOD. Returns the internal (string) id."""
        with self.connect().cursor() as cur:
            cur.execute(
                'SELECT id FROM videos WHERE "videoId" = %s', (video_id,)
            )
            row = cur.fetchone()
            if row:
                return row["id"]

            db_id = new_id()
            cur.execute(
                """
                INSERT INTO videos (
                    id, "channelId", "videoId", url, description, duration,
                    title, thumbnail, streamer, views, likes, language,
                    date, "createdAt", complete
                ) VALUES (
                    %(id)s, %(channelId)s, %(videoId)s, %(url)s, %(description)s,
                    %(duration)s, %(title)s, %(thumbnail)s, %(streamer)s,
                    %(views)s, 0, %(language)s, %(date)s, %(createdAt)s, false
                )
                ON CONFLICT ("videoId") DO UPDATE SET title = EXCLUDED.title
                RETURNING id
                """,
                {
                    "id": db_id,
                    "channelId": channel_id,
                    "videoId": video_id,
                    "url": meta["url"],
                    "description": meta["description"],
                    "duration": meta["duration"],
                    "title": meta["title"],
                    "thumbnail": meta["thumbnail"],
                    "streamer": meta["streamer"],
                    "views": meta["views"],
                    "language": meta["language"],
                    "date": meta["date"],
                    "createdAt": meta["date"],
                },
            )
            db_id = cur.fetchone()["id"]

            #Channel.videoIds is a scalar list the web app still reads
            cur.execute(
                """
                UPDATE channels
                   SET "videoIds" = array_append("videoIds", %(vid)s)
                 WHERE id = %(cid)s
                   AND NOT (%(vid)s = ANY("videoIds"))
                """,
                {"vid": db_id, "cid": channel_id},
            )
            return db_id

    def insert_comments(
        self, video_db_id: str, comments: Sequence[dict[str, Any]]
    ) -> int:
        """Bulk insert, skipping any comment already stored.

        Returns the number of rows actually written, so a resumed job does not
        double-count progress.
        """
        if not comments:
            return 0

        rows: list[tuple[Any, ...]] = [
            (
                new_id(),
                video_db_id,
                comment["message"],
                comment["commentId"],
                comment["commenter"],
                comment["contentOffsetSeconds"],
            )
            for comment in comments
        ]

        with self.connect().cursor() as cur:
            cur.executemany(
                """
                INSERT INTO msgs (
                    id, "vidId", message, "commentId", commenter,
                    "contentOffsetSeconds"
                ) VALUES (%s, %s, %s, %s, %s, %s)
                ON CONFLICT ("commentId") DO NOTHING
                """,
                rows,
            )
            return cur.rowcount or 0

    def count_comments(self, video_db_id: str) -> int:
        with self.connect().cursor() as cur:
            cur.execute(
                'SELECT count(*) AS n FROM msgs WHERE "vidId" = %s', (video_db_id,)
            )
            return int(cur.fetchone()["n"])

    def existing_comment_ids(self, video_db_id: str) -> set[str]:
        """Comment ids already stored, so a retried job skips re-inserting them."""
        with self.connect().cursor() as cur:
            cur.execute(
                'SELECT "commentId" FROM msgs WHERE "vidId" = %s', (video_db_id,)
            )
            return {row["commentId"] for row in cur.fetchall()}

    def upsert_emotes(self, emotes: Sequence[dict[str, Any]]) -> int:
        """Store a channel's emote images. Existing rows get refreshed URLs."""
        if not emotes:
            return 0

        rows = [
            (
                new_id(),
                emote["emojiId"],
                emote["name"],
                emote["gif"],
                emote["type"],
                emote["url1"],
                emote["url2"],
                emote["url3"],
            )
            for emote in emotes
        ]

        with self.connect().cursor() as cur:
            cur.executemany(
                """
                INSERT INTO emotes (
                    id, "emojiId", name, gif, type, url1, url2, url3
                ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s)
                ON CONFLICT ("emojiId") DO UPDATE
                    SET name = EXCLUDED.name,
                        gif  = EXCLUDED.gif,
                        type = EXCLUDED.type,
                        url1 = EXCLUDED.url1,
                        url2 = EXCLUDED.url2,
                        url3 = EXCLUDED.url3
                """,
                rows,
            )
            return cur.rowcount or 0

    def upsert_terms(self, channel_id: str, terms: Sequence[dict[str, Any]]) -> int:
        """Store per-channel emote usage counts.

        Must run after upsert_emotes: terms."emojiId" is a foreign key onto
        emotes."emojiId", so the emote row has to exist first.
        """
        if not terms:
            return 0

        rows = [
            (
                new_id(),
                channel_id,
                term["emojiId"],
                term["term"],
                term["amount"],
                term["type"],
            )
            for term in terms
        ]

        with self.connect().cursor() as cur:
            cur.executemany(
                """
                INSERT INTO terms (
                    id, "channelId", "emojiId", term, amount, type
                ) VALUES (%s, %s, %s, %s, %s, %s)
                ON CONFLICT ("channelId", "emojiId") DO UPDATE
                    SET amount = EXCLUDED.amount,
                        term   = EXCLUDED.term,
                        type   = EXCLUDED.type
                """,
                rows,
            )
            return cur.rowcount or 0

    def mark_video_complete(self, video_db_id: str) -> None:
        with self.connect().cursor() as cur:
            cur.execute(
                "UPDATE videos SET complete = true WHERE id = %s", (video_db_id,)
            )
